parameters.jsCode:
const update = $input.first().json;
let parsed = { type: 'unknown', raw: update };

if (update.message) {
  const text = update.message.text || '';
  if (text.startsWith('/start')) parsed.type = 'command_start';
  else if (text === '/skip') parsed.type = 'text_message';
  else if (text) parsed.type = 'text_message';
  else parsed.type = 'other_message';
  parsed.chat_id = update.message.chat.id;
  parsed.user_id = update.message.from.id;
  parsed.message_id = update.message.message_id;
  parsed.text = text;
  parsed.username = update.message.from.username || update.message.from.first_name || 'tam';
} else if (update.callback_query) {
  parsed.type = 'callback_query';
  parsed.chat_id = update.callback_query.message.chat.id;
  parsed.user_id = update.callback_query.from.id;
  parsed.message_id = update.callback_query.message.message_id;
  parsed.callback_data = update.callback_query.data;
  parsed.callback_id = update.callback_query.id;
  parsed.username = update.callback_query.from.username || update.callback_query.from.first_name || 'tam';
  const parts = (parsed.callback_data || '').split(':');
  parsed.cb_namespace = parts[0] || '';
  parsed.cb_pub_id = parts[1] || '';
  parsed.cb_stage = parts[2] || '';
  parsed.cb_action = parts[3] || '';
  parsed.cb_extra = parts.slice(4).join(':') || '';
    // C3: przycisk Pomiń -> udawaj wpisany /skip, ale zostaw type=callback (ACK zadziala)
  if (parsed.cb_action === 'skip') {
    parsed.is_skip_callback = true;
    parsed.text = '/skip';
  }
}

return [{ json: parsed }];

