parameters.jsCode:
const data = $('Parse Incoming').first().json;
const typeMap = {
  'rolka_ofertowa': 'Rolka_Ofertowa',
  'rolka_edukacyjna': 'Rolka_Edukacyjna',
  'blog': 'Blog_edukacyjny',
  'rolka_blog': 'Rolka_z_blogiem_edukacyjna'
};
const typPubMap = {
  'rolka_ofertowa': 'Rolka Ofertowa',
  'rolka_edukacyjna': 'Rolka Edukacyjna',
  'blog': 'Blog Edukacyjny',
  'rolka_blog': 'Rolka + Blog'
};
const typSesji = typeMap[data.cb_action] || 'Rolka_Ofertowa';
const typPublikacji = typPubMap[data.cb_action] || 'Rolka Ofertowa';
const initialStage = data.cb_action === 'rolka_ofertowa' ? 'numer_dzialki' : 'temat_edukacyjny';
return [{ json: { chat_id: data.chat_id, username: data.username, typ_sesji: typSesji, initial_stage: initialStage, typ_publikacji: typPublikacji, cb_action: data.cb_action } }];

const sesja = $input.first().json;
const input = $('Parse Incoming').first().json;                                
const action = input.cb_action || '';                                 
const currentStage = sesja['Aktualny krok'];
const pubId = Array.isArray(sesja['Powiązana publikacja']) ? sesja['Powiązana publikacja'][0] : sesja['Powiązana publikacja'];

// GUARD: post-generation flow (no callback) — passthrough z new_stage z Sesji
if (!action) {
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      current_stage: currentStage,
      new_stage: currentStage,
      action: '',
      trigger_sub_workflow: '',
      edytowane_pole: '',
      is_edit_mode: false,
      is_graphics_select: false
    }
  }];
}

// GUARD: Sesja w fazie zbierania danych (pre-gen) — callback nie powinien tu trafic.
const preGenStages = ['wybor_typu', 'numer_dzialki', 'temat_edukacyjny',
'dodatkowe_info', 'wizja_rolki', 'wybor_muzyki', 'foto_wybor', 'generowanie'];
if (preGenStages.includes(currentStage)) {
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      current_stage: currentStage,
      new_stage: currentStage,
      action: action || '',
      trigger_sub_workflow: '',
      edytowane_pole: '',
      skip_message: true,
      skip_reason: 'pre_gen_stage'
    }
  }];
}

const nextStage = {
  'reel_hashtags_pending': 'reel_script_pending',
  'reel_script_pending': 'reel_fb_text_pending',
  'reel_fb_text_pending': 'reel_ig_text_pending',
  'reel_ig_text_pending': 'reel_tiktok_text_pending',
  'reel_tiktok_text_pending': 'reel_preview_pending',
  'reel_preview_pending': 'reel_render_pending',
  'reel_render_pending': 'reel_complete',
  'reel_complete': 'session_publishing',
  'blog_sections_pending': 'blog_seo_pending',
  'blog_seo_pending': 'blog_graphics_pending',
  'blog_graphics_pending': 'blog_graphics_tresc_pending',
  'blog_graphics_tresc_pending': 'blog_featured_pending',
  'blog_featured_pending': 'blog_preview_pending',
  'blog_preview_pending': 'blog_complete',
  'blog_complete': 'session_publishing'
};

const prevStage = {};
Object.entries(nextStage).forEach(([from, to]) => { prevStage[to] = from; });

let newStage = currentStage;
let triggerSubWorkflow = '';

if (action === 'approve') {
  if (currentStage === 'reel_render_pending') {
    // P0-6: NIE awansuj do complete na klik usera.
    // reel_complete ustawia dopiero MB_Video_Render po zapisaniu URL Rolki.
    newStage = 'reel_render_pending';
    triggerSubWorkflow = '';
  } else {
    newStage = nextStage[currentStage] || currentStage;
    if (newStage === 'reel_render_pending') triggerSubWorkflow = 'video_render';
    if (newStage === 'session_publishing') triggerSubWorkflow = 'publish';
  }
} else if (action.startsWith('hero_')) {
  const heroNum = parseInt(action.replace('hero_', ''));
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      current_stage: currentStage,
      new_stage: 'blog_graphics_tresc_pending',
      action: 'hero_select',
      trigger_sub_workflow: '',
      hero_num: heroNum,
      is_edit_mode: false,
      is_graphics_select: true,
      is_hero_select: true
    }
  }];
} else if (action.startsWith('choose_')) {
  const trescNum = parseInt(action.replace('choose_', ''));
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      current_stage: currentStage,
      new_stage: 'blog_featured_pending',
      action: 'tresc_select',
      trigger_sub_workflow: '',
      tresc_num: trescNum,
      is_edit_mode: false,
      is_graphics_select: true,
      is_tresc_select: true
    }
  }];
    } else if (action.startsWith('delete_confirm_')) {
  // 🗑️ POTWIERDZONE — wykonaj usuniecie sekcji N
  const n = parseInt(action.replace('delete_confirm_', ''), 10) || 0;
  return [{ json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: currentStage,                 // zostajemy na blog_sections_pending
    action: 'delete_exec',
    trigger_sub_workflow: '',
    edytowane_pole: '',
    is_edit_mode: false,
    is_graphics_select: false,
    is_regen_input_mode: false,
    is_delete_ask: false,
    is_delete_exec: true,
    delete_section_num: n
  }}];
} else if (action.startsWith('delete_section_')) {
  // 🗑️ KLIK — zapytaj o potwierdzenie usuniecia sekcji N
  const n = parseInt(action.replace('delete_section_', ''), 10) || 0;
  return [{ json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: currentStage,
    action: 'delete_ask',
    trigger_sub_workflow: '',
    edytowane_pole: '',
    is_edit_mode: false,
    is_graphics_select: false,
    is_regen_input_mode: false,
    is_delete_ask: true,
    is_delete_exec: false,
    delete_section_num: n
  }}];
} else if (action === 'edit' || action.startsWith('slide_') || action.startsWith('section_')) {
  const slideMatch = action.match(/^slide_(\d+)$/);
  const sectionMatch = action.match(/^section_(\d+)$/);
  const slideNum = slideMatch ? parseInt(slideMatch[1]) : 0;
  const sectionNum = sectionMatch ? parseInt(sectionMatch[1]) : 0;

  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      current_stage: currentStage,
      new_stage: currentStage,
      action: 'edit',
      trigger_sub_workflow: '',
      edytowane_pole: input.cb_stage,
      edytowane_slajd: slideNum,
      edytowana_sekcja: sectionNum,  // ← NEW
      is_edit_mode: true
    }
  }];
} else if (action.startsWith('regen_slide_') || action.startsWith('regen_section_')) {
    const slideMatch = action.match(/^regen_slide_(\d+)$/);
    const sectionMatch = action.match(/^regen_section_(\d+)$/);
    const slideNum = slideMatch ? parseInt(slideMatch[1]) : 0;
    const sectionNum = sectionMatch ? parseInt(sectionMatch[1]) : 0;
    const scope = slideNum > 0 ? 'scenariusz_slide' : 'sections_section';
    return [{
      json: {
        sesja_id: sesja.id,
        publication_id: pubId,
        chat_id: sesja['ID chatu Telegram'],
        typ_sesji: sesja['Typ Sesji'],
        current_stage: currentStage,
        new_stage: currentStage,
        action: 'regen_ask_input',
        trigger_sub_workflow: '',
        regen_scope: scope,
        regen_slide_num: slideNum,
        regen_section_num: sectionNum,
        is_regen_input_mode: true,
        edytowane_pole: '',
        is_edit_mode: false
      }
    }];
} else if (action === 'regen') {
    const regenMap = {
      'reel_hashtags_pending':    'hashtags',
      'reel_script_pending':      'scenariusz',
      'reel_fb_text_pending':     'fb_text',
      'reel_ig_text_pending':     'ig_text',
      'reel_tiktok_text_pending': 'tiktok_text',
      'reel_preview_pending':     'preview',
      'reel_render_pending':      'render',
      'blog_sections_pending':    'sections',
      'blog_seo_pending':         'seo',
      'blog_graphics_pending':    'graphics'
    };
    const scope = regenMap[currentStage] || 'all';
    return [{
      json: {
        sesja_id: sesja.id,
        publication_id: pubId,
        chat_id: sesja['ID chatu Telegram'],
        typ_sesji: sesja['Typ Sesji'],
        current_stage: currentStage,
        new_stage: currentStage,
        action: 'regen_ask_input',
        trigger_sub_workflow: '',
        regen_scope: scope,
        is_regen_input_mode: true,
        edytowane_pole: '',
        is_edit_mode: false
      }
    }];
} else if (action === 'back') {
  newStage = prevStage[currentStage] || currentStage;
} else if (action === 'menu') {
  // C1 MVP: podmenu skoku „Wroc do etapu…" — NIE zmienia etapu (praca bezpieczna, nic nie kasuje)
  return [{ json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: currentStage,
    action: 'nav_menu',
    trigger_sub_workflow: '',
    edytowane_pole: '',
    is_edit_mode: false,
    is_graphics_select: false,
    is_nav_menu: true
  }}];
} else if (action.startsWith('goto_')) {
  // C1 MVP: skok do dowolnego etapu POST-GEN (sam wskaznik new_stage; zero regeneracji, zero utraty danych)
  const gotoMap = {
    goto_hashtags:'reel_hashtags_pending', goto_script:'reel_script_pending',
    goto_fb:'reel_fb_text_pending', goto_ig:'reel_ig_text_pending',
    goto_tiktok:'reel_tiktok_text_pending', goto_preview:'reel_preview_pending',
    goto_sections:'blog_sections_pending', goto_seo:'blog_seo_pending',
    goto_graphics:'blog_graphics_pending', goto_featured:'blog_featured_pending',
    goto_blog_preview:'blog_preview_pending'
  };
  newStage = gotoMap[action] || currentStage;   // trigger_sub_workflow zostaje ''
} else if (
  action === 'publish_now' || action === 'publish_all' ||
  action === 'publish_fb' || action === 'publish_ig' || action === 'publish_tt' ||
  action === 'publish_wp'
) {
  newStage = 'session_publishing';
  triggerSubWorkflow = 'publish';
} else if (action === 'schedule' || action === 'schedule_all') {
  newStage = 'session_publishing';
  triggerSubWorkflow = 'schedule';
} else if (action === 'blog') {
  const typ = (sesja['Typ Sesji'] || '').toLowerCase();
  if (typ.includes('blog')) {
    // Combo / Blog_*: blog juz jest — pokaz sekcje do edycji, bez sub-workflowa
    newStage = 'blog_sections_pending';
    triggerSubWorkflow = '';
  } else {
    // Samodzielna rolka → blog jeszcze NIE istnieje: odpal generacje bloga
    newStage = 'generowanie';            // transient — Build Stage Message pokaze spinner
    triggerSubWorkflow = 'blog_generate';
  }
} else if (action === 'regen_now') {
  // C5-B Part 1: "Odrzuc i generuj kolejne" — natychmiastowy regen grafik bez pytania o wskazowki
  return [{ json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: currentStage,
    action: 'graphics_regen_now',
    trigger_sub_workflow: '',
    is_graphics_regen_now: true,
    is_edit_mode: false,
    is_graphics_select: false
  }}];
} else if (action === 'hist_prev' || action === 'hist_next') {
  // C5-B Part 2: powrot do wczesniejszej/nastepnej partii grafik (koszt 0)
  return [{ json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: currentStage,
    action: action,
    trigger_sub_workflow: '',
    is_graphics_history: true,
    history_dir: action === 'hist_next' ? 1 : -1,
    is_edit_mode: false,
    is_graphics_select: false
  }}];
}

return [{
  json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    current_stage: currentStage,
    new_stage: newStage,
    action,
    trigger_sub_workflow: triggerSubWorkflow,
    edytowane_pole: action === 'edit' ? input.cb_stage : ''
  }
}];

const transition = $('State Transition Engine').isExecuted 
  ? $('State Transition Engine').first().json 
  : $('Bridge to Stage Message').first().json;
const pubRaw = $input.first().json;
const pub = pubRaw.fields ? { ...pubRaw.fields, id: pubRaw.id } : pubRaw;
const stage = transition.new_stage;
const pubId = transition.publication_id;
const chatId = transition.chat_id;

if (transition.skip_message) {
  return [{
    json: {
      chat_id: chatId,
      text: '⚠️ <b>Sesja jest w etapie zbierania danych.</b>\n\nOdpowiedz na ostatnią wiadomość bota albo użyj /start aby rozpocząć od nowa.',
      reply_markup: { inline_keyboard: [] }
    }
  }];
}
if (transition.is_nav_menu) {
  const isBlog = String(stage).startsWith('blog_');
  const navRows = isBlog ? [
    [{ text: '📄 Sekcje',  callback_data: `mb:${pubId}:nav:goto_sections` }, { text: '📊 SEO',     callback_data: `mb:${pubId}:nav:goto_seo` }],
    [{ text: '🖼️ Grafiki', callback_data: `mb:${pubId}:nav:goto_graphics` }, { text: '🌟 Featured', callback_data: `mb:${pubId}:nav:goto_featured` }],
    [{ text: '👀 Podgląd',  callback_data: `mb:${pubId}:nav:goto_blog_preview` }]
  ] : [
    [{ text: '🏷️ Hashtagi', callback_data: `mb:${pubId}:nav:goto_hashtags` }, { text: '🎬 Skrypt', callback_data: `mb:${pubId}:nav:goto_script` }],
    [{ text: '📘 FB', callback_data: `mb:${pubId}:nav:goto_fb` }, { text: '📸 IG', callback_data: `mb:${pubId}:nav:goto_ig` }, { text: '🎵 TikTok', callback_data: `mb:${pubId}:nav:goto_tiktok` }],
    [{ text: '👀 Podgląd', callback_data: `mb:${pubId}:nav:goto_preview` }]
  ];
  return [{ json: {
    chat_id: chatId,
    text: '🔙 <b>Wróć do etapu…</b>\n\nWybierz sekcję do poprawki. Twoja praca jest zapisana — skok niczego nie kasuje.',
    reply_markup: { inline_keyboard: navRows },
    album: []
  }}];
}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => esc(String(s || '').substring(0, n));

const reelStages = ['hashtags', 'script', 'fb_text', 'ig_text', 'tiktok_text', 'images', 'preview', 'render'];
const blogStages = ['sections', 'seo', 'graphics', 'graphics_tresc', 'featured', 'preview'];

let statusBar = '';
if (stage.startsWith('reel_')) {
  const cur = stage.replace('reel_', '').replace('_pending', '').replace('_approved', '');
  const curIdx = reelStages.indexOf(cur);
  const allDone = stage === 'reel_complete';
  statusBar = '<b>Rolka:</b> ' + reelStages.map((s, i) => {
    if (allDone) return '✅';
    if (curIdx === -1) return '⬜';
    if (i < curIdx) return '✅';
    if (i === curIdx) return stage.endsWith('_approved') ? '✅' : '⏳';
    return '⬜';
  }).join(' ') + '\n\n';
} else if (stage.startsWith('blog_')) {
  const cur = stage.replace('blog_', '').replace('_pending', '').replace('_approved', '');
  const curIdx = blogStages.indexOf(cur);
  const allDone = stage === 'blog_complete';
  statusBar = '<b>Blog:</b> ' + blogStages.map((s, i) => {
    if (allDone) return '✅';
    if (curIdx === -1) return '⬜';
    if (i < curIdx) return '✅';
    if (i === curIdx) return stage.endsWith('_approved') ? '✅' : '⏳';
    return '⬜';
  }).join(' ') + '\n\n';
}

let content = '';
let buttons = [];
let album = [];

const standardButtons = (s) => [
  [{text: '✅ Zatwierdz', callback_data: `mb:${pubId}:${s}:approve`}, {text: '✏️ Edytuj', callback_data: `mb:${pubId}:${s}:edit`}],
  [{text: '♻️ Regeneruj', callback_data: `mb:${pubId}:${s}:regen`}, {text: '⬅️ Wroc', callback_data: `mb:${pubId}:${s}:back`}]
];

switch (stage) {
  case 'reel_hashtags_pending':
    content = `🏷️ <b>Hashtagi</b>\n\n${esc(pub.Hashtagi) || '<i>(brak)</i>'}`;
    buttons = standardButtons('hashtags');
    break;

  case 'reel_script_pending': {
    let scenes = [];
    let narrationsText = '';
    try {
      const scenariusz = JSON.parse(pub['Wygenerowany scenariusz'] || '{}');
      scenes = scenariusz.scenes || [];
      narrationsText = scenes.map((s, i) => {
        let n = s.narration || s.text || '';
        if (!n && Array.isArray(s.elements)) {
          const voice = s.elements.find(e => e.type === 'voice');
          n = voice ? (voice.text || voice.narration || '') : '';
        }
        return `<b>Slajd ${i+1}:</b> ${esc(n) || '<i>(brak)</i>'}`;
      }).join('\n\n');
    } catch (e) {
      narrationsText = '<i>(błąd parsowania scenariusza)</i>';
    }
    content = `🎬 <b>Skrypt rolki</b>\n\n${narrationsText}\n\n<i>Klik numer slajdu żeby edytować</i>`;
  const slideButtons = [];
  const regenSlideButtons = [];
  for (let i = 1; i <= scenes.length; i++) {
    slideButtons.push({ text: `✏️  ${i}`, callback_data: `mb:${pubId}:script:slide_${i}` });
    regenSlideButtons.push({ text: `♻️  ${i}`, callback_data:
  `mb:${pubId}:script:regen_slide_${i}` });
  }
  buttons = [];
  for (let r = 0; r < slideButtons.length; r += 3) {
    buttons.push(slideButtons.slice(r, r + 3));
  }
  for (let r = 0; r < regenSlideButtons.length; r += 3) {
    buttons.push(regenSlideButtons.slice(r, r + 3));
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:script:approve` },
    { text: '♻️  Regen wszystko', callback_data: `mb:${pubId}:script:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:script:back` }
  ]);
    break;
  }

  case 'reel_fb_text_pending':
    content = `📘 <b>Tekst Facebook</b>\n\n${esc(pub.Opis_Facebook) || '<i>(brak)</i>'}`;
    buttons = standardButtons('fb_text');
    break;

  case 'reel_ig_text_pending':
    content = `📸 <b>Tekst Instagram</b>\n\n${esc(pub.Opis_Instagram) || '<i>(brak)</i>'}`;
    buttons = standardButtons('ig_text');
    break;

  case 'reel_tiktok_text_pending':
    content = `🎵 <b>Tekst TikTok</b>\n\n${esc(pub.Opis_TikTok) || '<i>(brak)</i>'}`;
    buttons = standardButtons('tiktok_text');
    break;

  case 'reel_preview_pending':
    content = `👀 <b>Preview rolki</b>\n\n<b>FB:</b> ${cut(pub.Opis_Facebook, 200)}...\n\n<b>IG:</b> ${cut(pub.Opis_Instagram, 200)}...\n\n<b>TikTok:</b> ${cut(pub.Opis_TikTok, 200)}...`;
    buttons = standardButtons('preview');
    break;

  case 'reel_render_pending':
    content = `🎥 <b>Render rolki w toku...</b>\n\nCzekaj na potwierdzenie — dam znac, gdy gotowe (~2 min).`;
    buttons = [];
    break;

  case 'reel_complete':
    content = `✅ <b>Rolka skonczona!</b>\n\nCo dalej?`;
    buttons = [
      [{text: '📝 Bloga teraz', callback_data: `mb:${pubId}:complete:blog`}],
      [{text: '🚀 Opublikuj rolke teraz', callback_data: `mb:${pubId}:complete:publish_now`}],
      [{text: '📅 Zaplanuj', callback_data: `mb:${pubId}:complete:schedule`}]
    ];
    break;

  case 'blog_sections_pending': {
    const html = pub['Treść Bloga (HTML)'] || '';
    const sections = [];

    // Section 0: Lead (wszystko przed pierwszym <h2>)
    const firstH2 = html.search(/<h2/i);
    if (firstH2 > 0) {
      const leadHtml = html.substring(0, firstH2).trim();
      if (leadHtml) {
        const titleMatch = leadHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
        sections.push({
          id: 1,
          title: '🎯 Lead (intro + tytul)',
          length: leadHtml.length,
          content: leadHtml
        });
      }
    }

    // H2 sections
    const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
    let match;
    while ((match = h2Regex.exec(html)) !== null) {
      const title = match[1].replace(/<[^>]+>/g, '').trim();
      const content = match[0];
      sections.push({
        id: sections.length + 1,
        title: title || 'Sekcja',
        length: content.length,
        content
      });
    }

    if (sections.length === 0) {
      content = `📝 <b>Blog (HTML pusty albo blad parsowania)</b>\n\n${cut(html, 800)}`;
      buttons = standardButtons('sections');
      break;
    }

    const menuLines = sections.map(s => `${s.id}. ${esc(s.title.substring(0, 60))} - ${s.length} znakow`).join('\n');
    content = `📝 <b>Tresc bloga - sekcje do edycji</b>\n\n${menuLines}\n\n<i>Klik numer zeby zobaczyc i edytowac</i>`;

  const sectionButtons = sections.map(s => ({
    text: `✏️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:section_${s.id}`
  }));
  const regenSectionButtons = sections.map(s => ({
    text: `♻️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:regen_section_${s.id}`
  }));

  buttons = [];
  for (let r = 0; r < sectionButtons.length; r += 3) {
    buttons.push(sectionButtons.slice(r, r + 3));
  }
  for (let r = 0; r < regenSectionButtons.length; r += 3) {
    buttons.push(regenSectionButtons.slice(r, r + 3));
  }
      // 🗑️ Usuń sekcję — tylko sekcje H2 (nie Lead=1) i tylko gdy po usunieciu zostanie >=1 sekcja H2
  const leadExists = firstH2 > 0 && html.substring(0, firstH2).trim().length > 0;
  const deletableIds = sections.filter(s => leadExists ? s.id >= 2 : true).map(s => s.id);
  if (deletableIds.length >= 2) {
    const deleteSectionButtons = deletableIds.map(id => ({
      text: `🗑️  ${id}`,
      callback_data: `mb:${pubId}:sections:delete_section_${id}`
    }));
    for (let r = 0; r < deleteSectionButtons.length; r += 3) {
      buttons.push(deleteSectionButtons.slice(r, r + 3));
    }
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:sections:approve` },
    { text: '♻️  Regen wszystko', callback_data: `mb:${pubId}:sections:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:sections:back` }
  ]);
    break;
  }

  case 'blog_seo_pending':
    content = `📊 <b>SEO</b>\n\n<b>Tytul:</b> ${esc(pub.Blog_Tytul)}\n<b>Meta:</b> ${esc(pub.Blog_Meta_Description)}\n<b>Slug:</b> ${esc(pub.Blog_Slug)}`;
    buttons = [
      [{ text: '✏️ Tytul', callback_data: `mb:${pubId}:seo_title:edit` }],
      [{ text: '✏️ Meta',  callback_data: `mb:${pubId}:seo_meta:edit` }],
      [{ text: '✏️ Slug',  callback_data: `mb:${pubId}:seo_slug:edit` }],
      [{ text: '✅ Zatwierdz SEO', callback_data: `mb:${pubId}:seo:approve` }, { text: '♻️ Regen', callback_data: `mb:${pubId}:seo:regen` }],
      [{ text: '⬅️ Wroc', callback_data: `mb:${pubId}:seo:back` }]
    ];
    break;

  case 'blog_graphics_pending':
    content = `🖼️ <b>Wybierz grafikę FEATURED</b> (hero — na początek bloga)\n\n` +
      `Poniżej 3 wygenerowane grafiki 👇 Wybierz numer przyciskiem.`;
    album = [1, 2, 3]
      .map(n => ({ type: 'photo', media: String(pub[`Blog_Grafika_URL_${n}`] || '').trim(), caption: `${n}` }))
      .filter(p => p.media);
    buttons = [
      [
        { text: '1️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_1` },
        { text: '2️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_2` },
        { text: '3️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_3` }
      ],
      [{ text: '🔄 Odrzuć i generuj kolejne', callback_data: `mb:${pubId}:graphics:regen_now` }],
      ...((() => { let h = []; try { h = JSON.parse(pub['Blog_Grafika_Historia'] || '[]'); } catch (e) {} return h.length > 1 ? [[
        { text: '⬅️ Poprzednia partia', callback_data: `mb:${pubId}:graphics:hist_prev` },
        { text: '➡️ Następna', callback_data: `mb:${pubId}:graphics:hist_next` }
      ]] : []; })()),
      [{ text: '⬅️ Wróć', callback_data: `mb:${pubId}:graphics:back` }]
    ];
    break;

  case 'blog_graphics_tresc_pending': {
    const heroIdx = transition.hero_num || pub.Blog_Grafika_Wybrana_Hero || 0;
    const remaining = [1, 2, 3].filter(n => n !== heroIdx);
        album = remaining
      .map(n => ({ type: 'photo', media: String(pub[`Blog_Grafika_URL_${n}`] || '').trim(), caption: `${n}` }))
      .filter(p => p.media);
content = `🖼️ <b>Wybierz grafikę TRESCI</b> (środek artykułu)\n\n` +
  `<b>Featured już wybrane:</b> grafika ${heroIdx}\n\n` +
  `Poniżej pozostałe grafiki 👇 Wybierz numer (Treść) przyciskiem.`
    buttons = [
      remaining.map(n => ({ text: `${n}️⃣ Treść`, callback_data: `mb:${pubId}:graphics_tresc:choose_${n}` })),
      [{ text: '⬅️ Wróć (zmień featured)', callback_data: `mb:${pubId}:graphics_tresc:back` }]
    ];
    break;
  }

  case 'blog_featured_pending':
    content = `🌟 <b>Featured Image</b>\n\n${esc(pub.Blog_Grafika_Finalna_URL) || '<i>(brak)</i>'}\n\n<b>Treść:</b> ${esc(pub.Blog_Grafika_Tresc_URL) || '<i>(brak)</i>'}`;
    buttons = standardButtons('featured');
    break;

  case 'blog_preview_pending':
    content = `👀 <b>Preview blogu</b>\n\n<b>${esc(pub.Blog_Tytul)}</b>\n${esc(pub.Blog_Meta_Description)}\n\n<i>Slug: ${esc(pub.Blog_Slug)}</i>`;
    buttons = standardButtons('preview');
    break;

  case 'blog_complete':
    content = `✅ <b>Blog skonczony!</b>`;
    buttons = [
      [{text: '🌐 Publikuj na WordPress', callback_data: `mb:${pubId}:complete:publish_wp`}],
      [{text: '📅 Zaplanuj', callback_data: `mb:${pubId}:complete:schedule_all`}]
    ];
    break;

  case 'session_publishing': {
    const platLabels = {
      publish_fb:  'Facebooku',
      publish_ig:  'Instagramie',
      publish_tt:  'TikToku',
      publish_wp:  'WordPress',
      publish_all: 'wszystkich platformach (FB / IG / TikTok)',
      publish_now: 'wszystkich platformach (FB / IG / TikTok)'
    };
    const label = platLabels[transition.action] || 'wybranej platformie';
    content = `⏳ <b>Publikuję na: ${esc(label)}...</b>`;
    buttons = [];
    break;
  }
  case 'generowanie':
    content = `📝 <b>Generuję bloga…</b>\n\nDaj mi chwilę (~2 min) — zaraz wrzucę sekcje do edycji.`;
    buttons = [];
    break;
  default:
    content = `Nieznany stage: ${esc(stage)}`;
    buttons = [];
}
const navEligible = (String(stage).startsWith('reel_') || String(stage).startsWith('blog_'))
  && stage !== 'reel_render_pending' && stage !== 'reel_draft' && stage !== 'blog_draft';
if (navEligible) {
  buttons = [...buttons, [{ text: '🔙 Wróć do etapu…', callback_data: `mb:${pubId}:nav:menu` }]];
}
return [{
  json: {
    chat_id: chatId,
    text: statusBar + content,
    reply_markup: { inline_keyboard: buttons },
    album: album
  }
}];

