parameters.jsCode:
const all = $input.all().map(i => i.json);

const tryGet = (nodeName) => {
  try { const items = $(nodeName).all(); return items.length ? items[0].json : null; }
  catch (e) { return null; }
};

// C5-A: dodane 'Get Sesja for Music CB' (potrzebne przy nawigacji Inne/Poprzednie)
const sesja = tryGet('Get Sesja (text)')
           || tryGet('Get Sesja for Foto CB')
           || tryGet('Get Sesja for Music CB')
           || tryGet('Get Sesja (callback)')
           || {};
const fields = sesja.fields || sesja || {};
const typSesji = fields['Typ Sesji'] || sesja['Typ Sesji'] || '';
const chatId = fields['ID chatu Telegram'] || sesja['ID chatu Telegram'];

const kat = typSesji.includes('Ofertowa') ? ['Ofertowe', 'Rolka'] : ['Edukacyjne', 'Rolka'];
const filtered = all.filter(r => {
  const k = r['Kategoria (Dla jakiego typu)'];
  const arr = Array.isArray(k) ? k : (k ? [k] : []);
  return arr.some(x => kat.includes(x));
});

// C5-A: tabela muzyki jest LOSOWANA w Airtable (kolejnosc niestabilna miedzy zapytaniami).
// Narzucamy DETERMINISTYCZNY porzadek per sesja (hash record_id + seed), zeby offset/historia
// dzialaly (te same 4 przy "Poprzednie", brak powtorek przy "Inne"). Seed per sesja => inny
// zestaw w kazdej nowej sesji (efekt "losowy" zachowany), ale STABILNY w trakcie wyboru.
const seed = String(chatId || '') + ':' + String(fields.id || sesja.id || '');
const hash = (str) => { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const order = filtered.slice().sort((a, b) => hash(String(a.id) + seed) - hash(String(b.id) + seed));

// C5-A: offset — przy nawigacji z 'Update Music Offset', inaczej z sesji (Muzyka_Batch_Offset)
const navOff = tryGet('Update Music Offset');
const offRaw = navOff ? navOff.new_offset : (parseInt(fields['Muzyka_Batch_Offset'] || 0, 10) || 0);
const len = order.length;
const off = len ? (((offRaw % len) + len) % len) : 0;
const hasMore = len > 4;

const batch = [];
for (let k = 0; k < Math.min(4, len); k++) batch.push(order[(off + k) % len]);

return batch.map((r, i) => {
  const zasob = r['Zasób'];
  const audioUrl = (Array.isArray(zasob) && zasob[0]) ? zasob[0].url : '';
  return {
    json: {
      record_id: r.id,
      name: r.Nazwa || `Utwór ${i + 1}`,
      audio_url: audioUrl,
      index: i + 1,
      chat_id: chatId,
      _has_more: hasMore
    }
  };
});

const sesja = $('Get Sesja (text)').first().json;
const typSesji = (sesja['Typ Sesji'] || '').toLowerCase();
const kategoria = typSesji.includes('ofertowa') ? 'ofertowe' : 'edukacyjne';
const all = $input.all().map(i => i.json);
const matching = all.filter(r => {
  const k = r['Kategoria (Dla jakiego typu)'];
  const arr = Array.isArray(k) ? k : (k ? [k] : []);
  return arr.some(x => (x || '').toLowerCase().includes(kategoria));
});
const inputText = ($('Parse Incoming').first().json.text || '').trim();
const num = parseInt(inputText, 10);
let selectedId = '';
let selectedName = '';
if (!isNaN(num) && num >= 1 && num <= matching.length) {
  selectedId = matching[num - 1].id;
  selectedName = matching[num - 1].Nazwa;
}
return [{
  json: {
    sesja_id: sesja.id,
    selected_id: selectedId,
    selected_name: selectedName,
    valid: !!selectedId,
    chat_id: $('Parse Incoming').first().json.chat_id
  }
}];

const raw = $input.first().json;
const sesja = raw.fields ? raw.fields : raw;

const pubArr = sesja['Powiązana publikacja'];
const pubId = Array.isArray(pubArr) ? pubArr[0] : (pubArr || '');
const chatId = $('Parse Incoming').first().json.chat_id;

return [{
  json: {
    sesja_id: raw.id || sesja.id,
    publication_id: pubId,
    chat_id: chatId,
    typ_sesji: sesja['Typ Sesji'] || ''
  }
}];

const sesja = $input.first().json;
const input = $('Parse Incoming').first().json;
const editedField = sesja['Edytowane Pole'];
const newText = input.text;
const pubId = Array.isArray(sesja['Powiązana publikacja']) ? sesja['Powiązana publikacja'][0] : sesja['Powiązana publikacja'];

const fieldMap = {
  'hashtags': 'Hashtagi',
  'script': 'Wygenerowany scenariusz',
  'fb_text': 'Opis_Facebook',
  'ig_text': 'Opis_Instagram',
  'tiktok_text': 'Opis_TikTok',
  'sections': 'Treść Bloga (HTML)',
  'seo': 'Blog_Meta_Description'
};

const airtableField = fieldMap[editedField] || editedField;
const newStage = `${sesja['Aktualny krok'].includes('reel_') ? 'reel_' : 'blog_'}${editedField}_approved`;

return [{
  json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: input.chat_id,
    typ_sesji: sesja['Typ Sesji'],
    airtable_field: airtableField,
    new_text: newText,
    new_stage: newStage,
    edytowane_pole_clear: ''
  }
}];

