const items = $('Build Music Message').all().map(i => i.json);
const chatId = items[0]?.chat_id;
const hasMore = items[0]?._has_more;

const buttons = items.map(it => ({
  text: String(it.index),
  callback_data: `mb:music:${it.record_id}`
}));

const text = `🎵 Wybierz utwór klikając numer:\n\n${items.map(it => `${it.index}.${it.name}`).join('\n')}`;

// C5-A: rząd nawigacji (paginacja puli) — tylko gdy jest więcej niż 4 utwory
const rows = [buttons];
if (hasMore) {
  rows.push([
    { text: '🔄 Inne propozycje', callback_data: 'mb:music:__next__' },
    { text: '⬅️ Poprzednie', callback_data: 'mb:music:__prev__' }
  ]);
}

return [{ json: { chat_id: chatId, text, reply_markup: { inline_keyboard: rows } } }];

const t = $('State Transition Engine').first().json;
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
tomorrow.setHours(12, 0, 0, 0);
return [{
  json: {
    id: t.publication_id,            // ← rekord do UPDATE (matchingColumns: ["id"])
    publication_id: t.publication_id,
    chat_id: t.chat_id,
    scheduled_at: tomorrow.toISOString()
  }
}];

const t = $('State Transition Engine').first().json;
const action = t.action || '';
const typ = (t.typ_sesji || '').toLowerCase();

const isRolka = typ.includes('rolka');
const isBlog = typ.includes('blog');

let platforms = [];

// Single platform z guardem
if (action === 'publish_fb') platforms = isRolka ? ['Facebook'] : [];
else if (action === 'publish_ig') platforms = isRolka ? ['Instagram'] : [];
else if (action === 'publish_tt') platforms = isRolka ? ['TikTok'] : [];
else if (action === 'publish_wp') platforms = ['WordPress'];
// Rolka context (Notify Success po renderze)
else if (action === 'publish_all' || action === 'publish_now') {
  if (isRolka) platforms.push('Facebook', 'Instagram', 'TikTok');
}
// Schedule (każdy typ)
else if (action === 'schedule_all' || action === 'schedule') {
  if (isRolka) platforms.push('Facebook', 'Instagram', 'TikTok');
  if (isBlog) platforms.push('WordPress');
}

return platforms.map(p => ({
  json: {
    publication_id: t.publication_id,
    platform: p,
    chat_id: t.chat_id
  }
}));

const dzialkaList = $('Dropbox List Dzialka').all().map(i => i.json);
const drogaList = $('Dropbox List Droga').all().map(i => i.json);

const isPhoto = (item) => /\.(jpg|jpeg|png)$/i.test(item.name || '');
const getPath = (item) => item.pathLower || item.pathDisplay ||
item.path_lower || item.path_display || '';

// Droga: max 2, posortowane
const drogaPhotos = drogaList
  .filter(isPhoto)
  .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
  .slice(0, 2)
  .map(item => ({
    name: item.name,
    path: getPath(item),
    source: 'droga'
  }));

// Działka: max (13 - droga.length), posortowane
const maxDzialka = 13 - drogaPhotos.length;
const dzialkaPhotos = dzialkaList
  .filter(isPhoto)
  .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
  .slice(0, maxDzialka)
  .map(item => ({
    name: item.name,
    path: getPath(item),
    source: 'dz'
  }));

const combined = [...dzialkaPhotos, ...drogaPhotos];

return combined.map((p, i) => ({
  json: {
    index: i + 1,
    name: p.name,
    path: p.path,
    source: p.source,
    chat_id: $('Get Sesja for Music CB').first().json.fields?.['ID chatu Telegram'] || $('Get Sesja for Music CB').first().json['ID chatu Telegram'],
    sesja_id: $('Get Sesja for Music CB').first().json.id,
    publication_id: ($('Get Sesja for Music CB').first().json.fields?.['Powiązana publikacja'] || $('Get Sesja for Music CB').first().json['Powiązana publikacja'] || [])[0]
  }
}));

