const data = $('Save Lista Wszystkich Zdjec').first().json;
const items = $('Combine and Filter Photos').all().map(i => i.json);

const buttons = [];
const rows = Math.ceil(items.length / 4);
for (let r = 0; r < rows; r++) {
  const row = [];
  for (let c = 0; c < 4; c++) {
    const idx = r * 4 + c;
    if (idx >= items.length) break;
    row.push({
      text: String(items[idx].index),
      callback_data: `mb:foto:toggle:${items[idx].index}`
    });
  }
  buttons.push(row);
}
buttons.push([
  { text: '✅ Gotowe', callback_data: 'mb:foto:done' },
  { text: '⬅️ Wroc', callback_data: 'mb:foto:back' }
]);

return [{
  json: {
    chat_id: data.chat_id,
    text: '🖼 <b>Wybierz zdjecia do rolki</b>\n\nKlikaj numery aby zaznaczyc/odznaczyc. Kliknij ✅ Gotowe gdy skonczysz.',
    reply_markup: { inline_keyboard: buttons }
  }
}];

const sesja = $('Get Sesja for Foto CB').first().json;
const fields = sesja.fields || sesja;
const cb_action = $('Parse Incoming').first().json.cb_action; // numer zdjecia (string)
const num = cb_action;

const current = (fields['Wybrane Zdjęcia'] || '').split(',').map(s => s.trim()).filter(Boolean);

let updated;
if (current.includes(num)) {
  updated = current.filter(n => n !== num);
} else {
  updated = [...current, num];
}

return [{
  json: {
    sesja_id: sesja.id,
    chat_id: $('Parse Incoming').first().json.chat_id,
