    lista_wszystkich: fields['ListaWszystkichZdjec'] || ''
  }
}];

const data = $('Toggle Photo Selection').first().json;
const selected = data.selected_set;
const lista = data.lista_wszystkich.split(',').map(s => s.trim()).filter(Boolean);

// Reconstruct button labels with checkmarks
const total = Math.min(20, lista.length || 0);
const buttons = [];
const rows = Math.ceil(total / 4);
for (let r = 0; r < rows; r++) {
  const row = [];
  for (let c = 0; c < 4; c++) {
    const idx = r * 4 + c;
    if (idx >= total) break;
    const num = String(idx + 1);
    const isSelected = selected.includes(num);
    row.push({
      text: isSelected ? `${num}✓` : num,
      callback_data: `mb:foto:toggle:${num}`
    });
  }
  if (row.length) buttons.push(row);
}
buttons.push([
  { text: '✅ Gotowe', callback_data: 'mb:foto:done' },
  { text: '⬅️ Wroc', callback_data: 'mb:foto:back' }
]);

return [{
  json: {
    chat_id: data.chat_id,
    message_id: data.message_id,
    reply_markup: { inline_keyboard: buttons }
  }
}];

const t = $('State Transition Engine').first().json;
const pub = $('Get Publikacja for Display').first().json;

const stageLabels = {
  'hashtags': 'Hashtagi',
  'fb_text': 'Tekst Facebook',
  'ig_text': 'Tekst Instagram',
  'tiktok_text': 'Tekst TikTok',
  'sections': 'Tresc bloga',
  'seo_title': 'SEO — Tytul',
  'seo_meta': 'SEO — Meta description',
  'seo_slug': 'SEO — Slug'
};

const fieldMap = {
  'hashtags': 'Hashtagi',
  'fb_text': 'Opis_Facebook',
  'ig_text': 'Opis_Instagram',
  'tiktok_text': 'Opis_TikTok',
  'seo_title': 'Blog_Tytul',
  'seo_meta': 'Blog_Meta_Description',
  'seo_slug': 'Blog_Slug'
};

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let label, currentText;

if (t.edytowane_pole === 'script' && t.edytowane_slajd > 0) {
  // Per-slide edit (rolka)
  label = `Slajd ${t.edytowane_slajd} (skrypt)`;
  try {
    const scen = JSON.parse(pub['Wygenerowany scenariusz'] || '{}');
    const scene = (scen.scenes || [])[t.edytowane_slajd - 1];
    if (scene && Array.isArray(scene.elements)) {
      const voice = scene.elements.find(e => e.type === 'voice');
      currentText = voice ? (voice.text || voice.narration || '') : '';
    }
  } catch (e) {
    currentText = '(błąd parsowania)';
  }
} else if (t.edytowane_pole === 'sections' && t.edytowana_sekcja > 0) {
  // Per-section edit (blog)
  const html = pub['Treść Bloga (HTML)'] || '';
  const sections = [];

  const firstH2 = html.search(/<h2/i);
  if (firstH2 > 0) {
    sections.push({ title: 'Lead', content: html.substring(0, firstH2).trim() });
  }

  const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
  let m;
  while ((m = h2Regex.exec(html)) !== null) {
    const title = m[1].replace(/<[^>]+>/g, '').trim();
    sections.push({ title: title || 'Sekcja', content: m[0] });
  }

  const sec = sections[t.edytowana_sekcja - 1];
  label = `Sekcja ${t.edytowana_sekcja}: ${sec ? sec.title : '(brak)'}`;
  currentText = sec ? sec.content : '(sekcja poza zakresem)';
} else {
  label = stageLabels[t.edytowane_pole] || t.edytowane_pole;
  currentText = pub[fieldMap[t.edytowane_pole]] || '';
}

const plain = String(currentText || '').trim() || '(brak)';
const text = `✏️ <b>Edycja: ${label}</b>\n\n<b>Aktualny tekst:</b>\n<pre>${esc(currentText) || '(brak)'}</pre>\n\nSkopiuj tekst przyciskiem poniżej, zmień i odeślij. Lub /skip.`;
const rows = [];
if (plain.length <= 256) rows.push([{ text: '📋 Kopiuj tekst', copy_text: { text: plain } }]);
rows.push([{ text: '⏭️ Pomiń', callback_data: `mb:${t.publication_id}:${t.edytowane_pole}:skip` }]);
return [{ json: { chat_id: t.chat_id, text, reply_markup: { inline_keyboard: rows } } }];

return [{
  json: {
    chat_id: t.chat_id,
    text,
    reply_markup: { inline_keyboard: [[{ text: '⏭️ Pomiń', callback_data: `mb:${t.publication_id}:${t.edytowane_pole}:skip` }]] }
  }
}];

const sesja = $('Get Sesja (text)').first().json;
const text = $('Parse Incoming').first().json.text || '';
const edytowanePole = sesja['Edytowane Pole'];
const slideNum = sesja['Numer_slajdu_edycja'] || 0;
const sectionNum = sesja['Numer_sekcji_edycja'] || 0;
const pubId = Array.isArray(sesja['Powiązana publikacja']) ? sesja['Powiązana publikacja'][0] : sesja['Powiązana publikacja'];

const fieldMap = {
  'hashtags': 'Hashtagi',
  'fb_text': 'Opis_Facebook',
  'ig_text': 'Opis_Instagram',
  'tiktok_text': 'Opis_TikTok',
  'sections': 'Treść Bloga (HTML)',
  // P0-2: SEO rozbite na 3 pola
  'seo_title': 'Blog_Tytul',
  'seo_meta': 'Blog_Meta_Description',
  'seo_slug': 'Blog_Slug'
};

const nextStage = {
  'hashtags': 'reel_script_pending',
  'fb_text': 'reel_ig_text_pending',
  'ig_text': 'reel_tiktok_text_pending',
  'tiktok_text': 'reel_preview_pending',
  'sections': 'blog_sections_pending',
  // P0-2: po edycji pojedynczego pola SEO zostajemy na ekranie SEO (edycja kolejnych)
  'seo_title': 'blog_seo_pending',
  'seo_meta': 'blog_seo_pending',
  'seo_slug': 'blog_seo_pending'
};

// SCRIPT EDIT (rolka per slide)
if (edytowanePole === 'script' && slideNum > 0) {
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      airtable_field: 'Wygenerowany scenariusz',
      edited_value: text,
      slide_num: slideNum,
      is_script_edit: true,
      next_stage: 'reel_script_pending',
      skipped: text === '/skip'
    }
  }];
}

// SECTIONS EDIT (blog per section)
if (edytowanePole === 'sections' && sectionNum > 0) {
  return [{
    json: {
      sesja_id: sesja.id,
      publication_id: pubId,
      chat_id: sesja['ID chatu Telegram'],
      typ_sesji: sesja['Typ Sesji'],
      airtable_field: 'Treść Bloga (HTML)',
      edited_value: text,
      section_num: sectionNum,
      is_section_edit: true,
      next_stage: 'blog_sections_pending',  // zostaje, klientka edytuje dalsze
      skipped: text === '/skip'
    }
  }];
}

// STANDARD EDIT (hashtags, fb_text, seo_title, seo_meta, seo_slug, ...)
const airtableField = fieldMap[edytowanePole];

if (!airtableField) {
  return [{ json: { error: true, chat_id: sesja['ID chatu Telegram'], message: '⚠️ Nieznane pole edycji: ' + edytowanePole } }];
}

return [{
  json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: sesja['ID chatu Telegram'],
    typ_sesji: sesja['Typ Sesji'],
    airtable_field: airtableField,
    edited_value: text,
    next_stage: nextStage[edytowanePole] || 'reel_complete',
    is_script_edit: false,
    skipped: text === '/skip'
  }
}];

const saved = $('Save Edited Text').first().json;
return [{
  json: {
    sesja_id: saved.sesja_id,
    publication_id: saved.publication_id,
    chat_id: saved.chat_id,
    typ_sesji: saved.typ_sesji,
    current_stage: saved.next_stage,
    new_stage: saved.next_stage,
    action: 'approve',
    trigger_sub_workflow: '',
    edytowane_pole: '',
    is_edit_mode: false,
    skip_message: false
  }
}];

const saved = $('Save Edited Text').first().json;
const pub = $('Get Publikacja for Edit').first().json;
const slideNum = saved.slide_num;
const newText = saved.edited_value;

const scenarioRaw = pub.fields?.['Wygenerowany scenariusz'] ||
pub['Wygenerowany scenariusz'] || '{}';

let scen;
try {
  scen = JSON.parse(scenarioRaw);
} catch (e) {
  throw new Error('Niepoprawny JSON scenariusza: ' + e.message);
}

const scenes = scen.scenes || [];
if (slideNum < 1 || slideNum > scenes.length) {
  throw new Error('Slide num poza zakresem: ' + slideNum + ' (scenes: ' +
scenes.length + ')');
}

const scene = scenes[slideNum - 1];
if (Array.isArray(scene.elements)) {
  const voice = scene.elements.find(e => e.type === 'voice');
  if (voice) {
    voice.text = newText;
  } else {
    throw new Error('Brak voice element w slajdzie ' + slideNum);
  }
} else if (scene.narration !== undefined) {
  scene.narration = newText;
} else if (scene.text !== undefined) {
  scene.text = newText;
}

return [{
  json: {
    publication_id: saved.publication_id,
    sesja_id: saved.sesja_id,
    chat_id: saved.chat_id,
    new_scenario_json: JSON.stringify(scen),
    next_stage: saved.next_stage
  }
}];

