const saved = $('Save Edited Text').first().json;
const pub = $('Get Publikacja for Section Edit').first().json;
const sectionNum = saved.section_num;
const newSectionContent = saved.edited_value;

const scenarioRaw = pub.fields?.['Treść Bloga (HTML)'] || pub['Treść Bloga (HTML)'] || '';
const html = scenarioRaw;

// Parse sekcje
const sections = [];
const firstH2 = html.search(/<h2/i);
if (firstH2 > 0) {
  sections.push({ start: 0, end: firstH2, content: html.substring(0, firstH2) });
}

const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
let match;
while ((match = h2Regex.exec(html)) !== null) {
  sections.push({ start: match.index, end: match.index + match[0].length, content: match[0] });
}

if (sectionNum < 1 || sectionNum > sections.length) {
  throw new Error('Sekcja poza zakresem: ' + sectionNum + ' (sekcji: ' + sections.length + ')');
}

const sec = sections[sectionNum - 1];
const newHtml = html.substring(0, sec.start) + newSectionContent + html.substring(sec.end);

return [{
  json: {
    publication_id: saved.publication_id,
    sesja_id: saved.sesja_id,
    chat_id: saved.chat_id,
    new_html: newHtml,
    next_stage: saved.next_stage
  }
}];

const pubRaw = $input.first().json;
const pub = pubRaw.fields ? { ...pubRaw.fields, id: pubRaw.id } : pubRaw;
const chatId = $('State Transition Engine').first().json.chat_id;
const pubId = $('State Transition Engine').first().json.publication_id;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => esc(String(s || '').substring(0, n));

const html = pub['Treść Bloga (HTML)'] || '';
const sections = [];

const firstH2 = html.search(/<h2/i);
if (firstH2 > 0) {
  const leadHtml = html.substring(0, firstH2).trim();
  if (leadHtml) {
    sections.push({ id: 1, title: '🎯 Lead (intro + tytul)', length: leadHtml.length });
  }
}

const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
let match;
while ((match = h2Regex.exec(html)) !== null) {
  const title = match[1].replace(/<[^>]+>/g, '').trim();
  sections.push({ id: sections.length + 1, title: title || 'Sekcja', length: match[0].length });
}

let content, buttons;

if (sections.length === 0) {
  content = `✅ <b>Rolka opublikowana na FB/IG/TT!</b>\n\n📝 <b>Blog (HTML pusty albo blad
parsowania)</b>\n\n${cut(html, 800)}`;
  buttons = [
    [{text: '✅ Zatwierdz', callback_data: `mb:${pubId}:sections:approve`}, {text: '✏️  Edytuj', callback_data:
 `mb:${pubId}:sections:edit`}],
    [{text: '♻️  Regeneruj', callback_data: `mb:${pubId}:sections:regen`}, {text: '⬅️  Wroc', callback_data:
`mb:${pubId}:sections:back`}]
  ];
} else {
  const menuLines = sections.map(s => `${s.id}. ${esc(s.title.substring(0, 60))} - ${s.length}
znakow`).join('\n');
  content = `✅ <b>Rolka opublikowana na FB/IG/TT!</b>\n\n<b>Blog:</b> ⏳ ⬜ ⬜ ⬜ ⬜ ⬜\n\n📝 <b>Tresc bloga
- sekcje do edycji</b>\n\n${menuLines}\n\n<i>Klik numer zeby zobaczyc i edytowac</i>`;

  const sectionButtons = sections.map(s => ({
    text: `✏️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:section_${s.id}`
  }));

  buttons = [];
  for (let r = 0; r < sectionButtons.length; r += 3) {
    buttons.push(sectionButtons.slice(r, r + 3));
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:sections:approve` },
    { text: '♻️  Regen', callback_data: `mb:${pubId}:sections:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:sections:back` }
  ]);
}

return [{
  json: {
    chat_id: chatId,
    text: content,
    reply_markup: { inline_keyboard: buttons }
  }
}];

const data = $('Save Regen Input').first().json;

return [{
  json: {
    sesja_id: data.sesja_id,
    publication_id: data.publication_id,
    chat_id: data.chat_id,
    typ_sesji: data.typ_sesji,
    current_stage: data.current_stage,
    new_stage: data.current_stage,
    action: 'regen_done',
    trigger_sub_workflow: '',
    is_edit_mode: false,
    is_graphics_select: false
  }
}];

const transition = $('Prepare Regen Return').first().json;
const pubRaw = $input.first().json;
const pub = pubRaw.fields ? { ...pubRaw.fields, id: pubRaw.id } : pubRaw;
const stage = transition.new_stage;
const pubId = transition.publication_id;
const chatId = transition.chat_id;

if (transition.skip_message) {
  return [{
    json: {
      chat_id: chatId,
      text: '⚠️ <b>Sesja jest w etapie zbierania danych.</b>\n\nOdpowiedz na ostatnią wiadomość bota albo użyj /start aby rozpocząć od nowa.',
      reply_markup: { inline_keyboard: [] }
    }
  }];
}

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => esc(String(s || '').substring(0, n));

const reelStages = ['hashtags', 'script', 'fb_text', 'ig_text', 'tiktok_text', 'images', 'preview', 'render'];
const blogStages = ['sections', 'seo', 'graphics', 'graphics_tresc', 'featured', 'preview'];

let statusBar = '';
if (stage.startsWith('reel_')) {
  const cur = stage.replace('reel_', '').replace('_pending', '').replace('_approved', '');
  statusBar = '<b>Rolka:</b> ' + reelStages.map(s => {
    if (reelStages.indexOf(s) < reelStages.indexOf(cur)) return '✅';
    if (s === cur) return stage.endsWith('_approved') ? '✅' : '⏳';
    return '⬜';
  }).join(' ') + '\n\n';
} else if (stage.startsWith('blog_')) {
  const cur = stage.replace('blog_', '').replace('_pending', '').replace('_approved', '');
  statusBar = '<b>Blog:</b> ' + blogStages.map(s => {
    if (blogStages.indexOf(s) < blogStages.indexOf(cur)) return '✅';
    if (s === cur) return '⏳';
    return '⬜';
  }).join(' ') + '\n\n';
}

let content = '';
let buttons = [];
let album = [];

const standardButtons = (s) => [
  [{text: '✅ Zatwierdz', callback_data: `mb:${pubId}:${s}:approve`}, {text: '✏️ Edytuj', callback_data: `mb:${pubId}:${s}:edit`}],
  [{text: '♻️ Regeneruj', callback_data: `mb:${pubId}:${s}:regen`}, {text: '⬅️ Wroc', callback_data: `mb:${pubId}:${s}:back`}]
];

switch (stage) {
  case 'reel_hashtags_pending':
    content = `🏷️ <b>Hashtagi</b>\n\n${esc(pub.Hashtagi) || '<i>(brak)</i>'}`;
    buttons = standardButtons('hashtags');
    break;

  case 'reel_script_pending': {
    let scenes = [];
    let narrationsText = '';
    try {
      const scenariusz = JSON.parse(pub['Wygenerowany scenariusz'] || '{}');
      scenes = scenariusz.scenes || [];
      narrationsText = scenes.map((s, i) => {
        let n = s.narration || s.text || '';
        if (!n && Array.isArray(s.elements)) {
          const voice = s.elements.find(e => e.type === 'voice');
          n = voice ? (voice.text || voice.narration || '') : '';
        }
        return `<b>Slajd ${i+1}:</b> ${esc(n) || '<i>(brak)</i>'}`;
      }).join('\n\n');
    } catch (e) {
      narrationsText = '<i>(błąd parsowania scenariusza)</i>';
    }
    content = `🎬 <b>Skrypt rolki</b>\n\n${narrationsText}\n\n<i>Klik numer slajdu żeby edytować</i>`;
  const slideButtons = [];
  const regenSlideButtons = [];
  for (let i = 1; i <= scenes.length; i++) {
    slideButtons.push({ text: `✏️  ${i}`, callback_data: `mb:${pubId}:script:slide_${i}` });
    regenSlideButtons.push({ text: `♻️  ${i}`, callback_data:
  `mb:${pubId}:script:regen_slide_${i}` });
  }
  buttons = [];
  for (let r = 0; r < slideButtons.length; r += 3) {
    buttons.push(slideButtons.slice(r, r + 3));
  }
  for (let r = 0; r < regenSlideButtons.length; r += 3) {
    buttons.push(regenSlideButtons.slice(r, r + 3));
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:script:approve` },
    { text: '♻️  Regen wszystko', callback_data: `mb:${pubId}:script:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:script:back` }
  ]);
    break;
  }

  case 'reel_fb_text_pending':
    content = `📘 <b>Tekst Facebook</b>\n\n${esc(pub.Opis_Facebook) || '<i>(brak)</i>'}`;
    buttons = standardButtons('fb_text');
    break;

  case 'reel_ig_text_pending':
    content = `📸 <b>Tekst Instagram</b>\n\n${esc(pub.Opis_Instagram) || '<i>(brak)</i>'}`;
    buttons = standardButtons('ig_text');
    break;

  case 'reel_tiktok_text_pending':
    content = `🎵 <b>Tekst TikTok</b>\n\n${esc(pub.Opis_TikTok) || '<i>(brak)</i>'}`;
    buttons = standardButtons('tiktok_text');
    break;

  case 'reel_preview_pending':
    content = `👀 <b>Preview rolki</b>\n\n<b>FB:</b> ${cut(pub.Opis_Facebook, 200)}...\n\n<b>IG:</b> ${cut(pub.Opis_Instagram, 200)}...\n\n<b>TikTok:</b> ${cut(pub.Opis_TikTok, 200)}...`;
    buttons = standardButtons('preview');
    break;

  case 'reel_render_pending':
    content = `♻️ <b>Zregenerowano.</b>\n\nRender rolki NIE zostal automatycznie ponowiony. Kliknij „Wroc do podgladu" i zatwierdz, zeby wyrenderowac nowa wersje.`;
    buttons = [
      [{ text: '⬅️ Wroc do podgladu', callback_data: `mb:${pubId}:preview:back` }]
    ];
    break;

  case 'reel_complete':
    content = `✅ <b>Rolka skonczona!</b>\n\nCo dalej?`;
    buttons = [
      [{text: '📝 Bloga teraz', callback_data: `mb:${pubId}:complete:blog`}],
      [{text: '🚀 Opublikuj rolke teraz', callback_data: `mb:${pubId}:complete:publish_now`}],
      [{text: '📅 Zaplanuj', callback_data: `mb:${pubId}:complete:schedule`}]
    ];
    break;

  case 'blog_sections_pending': {
    const html = pub['Treść Bloga (HTML)'] || '';
    const sections = [];

    // Section 0: Lead (wszystko przed pierwszym <h2>)
    const firstH2 = html.search(/<h2/i);
    if (firstH2 > 0) {
      const leadHtml = html.substring(0, firstH2).trim();
      if (leadHtml) {
        const titleMatch = leadHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
        sections.push({
          id: 1,
          title: '🎯 Lead (intro + tytul)',
          length: leadHtml.length,
          content: leadHtml
        });
      }
    }

    // H2 sections
    const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
    let match;
    while ((match = h2Regex.exec(html)) !== null) {
      const title = match[1].replace(/<[^>]+>/g, '').trim();
      const content = match[0];
      sections.push({
        id: sections.length + 1,
        title: title || 'Sekcja',
        length: content.length,
        content
      });
    }

    if (sections.length === 0) {
      content = `📝 <b>Blog (HTML pusty albo blad parsowania)</b>\n\n${cut(html, 800)}`;
      buttons = standardButtons('sections');
      break;
    }

    const menuLines = sections.map(s => `${s.id}. ${esc(s.title.substring(0, 60))} - ${s.length} znakow`).join('\n');
    content = `📝 <b>Tresc bloga - sekcje do edycji</b>\n\n${menuLines}\n\n<i>Klik numer zeby zobaczyc i edytowac</i>`;

  const sectionButtons = sections.map(s => ({
    text: `✏️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:section_${s.id}`
  }));
  const regenSectionButtons = sections.map(s => ({
    text: `♻️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:regen_section_${s.id}`
  }));

  buttons = [];
  for (let r = 0; r < sectionButtons.length; r += 3) {
    buttons.push(sectionButtons.slice(r, r + 3));
  }
  for (let r = 0; r < regenSectionButtons.length; r += 3) {
    buttons.push(regenSectionButtons.slice(r, r + 3));
  }
      // 🗑️ Usuń sekcję — tylko sekcje H2 (nie Lead=1) i tylko gdy po usunieciu zostanie >=1 sekcja H2
  const leadExists = firstH2 > 0 && html.substring(0, firstH2).trim().length > 0;
  const deletableIds = sections.filter(s => leadExists ? s.id >= 2 : true).map(s => s.id);
  if (deletableIds.length >= 2) {
    const deleteSectionButtons = deletableIds.map(id => ({
      text: `🗑️  ${id}`,
      callback_data: `mb:${pubId}:sections:delete_section_${id}`
    }));
    for (let r = 0; r < deleteSectionButtons.length; r += 3) {
      buttons.push(deleteSectionButtons.slice(r, r + 3));
    }
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:sections:approve` },
    { text: '♻️  Regen wszystko', callback_data: `mb:${pubId}:sections:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:sections:back` }
  ]);
    break;
  }

  case 'blog_seo_pending':
    content = `📊 <b>SEO</b>\n\n<b>Tytul:</b> ${esc(pub.Blog_Tytul)}\n<b>Meta:</b> ${esc(pub.Blog_Meta_Description)}\n<b>Slug:</b> ${esc(pub.Blog_Slug)}`;
    buttons = [
      [{ text: '✏️ Tytul', callback_data: `mb:${pubId}:seo_title:edit` }],
      [{ text: '✏️ Meta',  callback_data: `mb:${pubId}:seo_meta:edit` }],
      [{ text: '✏️ Slug',  callback_data: `mb:${pubId}:seo_slug:edit` }],
      [{ text: '✅ Zatwierdz SEO', callback_data: `mb:${pubId}:seo:approve` }, { text: '♻️ Regen', callback_data: `mb:${pubId}:seo:regen` }],
      [{ text: '⬅️ Wroc', callback_data: `mb:${pubId}:seo:back` }]
    ];
    break;
  case 'blog_graphics_pending':
    content = `🖼️ <b>Wybierz grafikę FEATURED</b> (na początek bloga, hero image)\n\n` +
      `1. ${esc(pub.Blog_Grafika_URL_1) || '<i>(brak)</i>'}\n\n` +
      `2. ${esc(pub.Blog_Grafika_URL_2) || '<i>(brak)</i>'}\n\n` +
      `3. ${esc(pub.Blog_Grafika_URL_3) || '<i>(brak)</i>'}\n\n` +
      `<i>Klik link żeby zobaczyć, potem wybierz numer.</i>`;
        album = [1, 2, 3]
      .map(n => ({ type: 'photo', media: String(pub[`Blog_Grafika_URL_${n}`] || '').trim(), caption: `${n}` }))
      .filter(p => p.media);
    buttons = [
      [
        { text: '1️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_1` },
        { text: '2️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_2` },
        { text: '3️⃣ Featured', callback_data: `mb:${pubId}:graphics:hero_3` }
      ],
      [{ text: '🔄 Odrzuć i generuj kolejne', callback_data: `mb:${pubId}:graphics:regen_now` }],
      ...((() => { let h = []; try { h = JSON.parse(pub['Blog_Grafika_Historia'] || '[]'); } catch (e) {} return h.length > 1 ? [[
        { text: '⬅️ Poprzednia partia', callback_data: `mb:${pubId}:graphics:hist_prev` },
        { text: '➡️ Następna', callback_data: `mb:${pubId}:graphics:hist_next` }
      ]] : []; })()),
      [{ text: '⬅️ Wróć', callback_data: `mb:${pubId}:graphics:back` }]
    ];
    break;

  case 'blog_graphics_tresc_pending': {
    const heroIdx = transition.hero_num || pub.Blog_Grafika_Wybrana_Hero || 0;
    const remaining = [1, 2, 3].filter(n => n !== heroIdx);
        album = remaining
      .map(n => ({ type: 'photo', media: String(pub[`Blog_Grafika_URL_${n}`] || '').trim(), caption: `${n}` }))
      .filter(p => p.media);
content = `🖼️ <b>Wybierz grafikę TRESCI</b> (środek artykułu)\n\n` +
  `<b>Featured już wybrane:</b> grafika ${heroIdx}\n\n` +
  `Poniżej pozostałe grafiki 👇 Wybierz numer (Treść) przyciskiem.`
    buttons = [
      remaining.map(n => ({ text: `${n}️⃣ Treść`, callback_data: `mb:${pubId}:graphics_tresc:choose_${n}` })),
      [{ text: '⬅️ Wróć (zmień featured)', callback_data: `mb:${pubId}:graphics_tresc:back` }]
    ];
    break;
  }

  case 'blog_featured_pending':
    content = `🌟 <b>Featured Image</b>\n\n${esc(pub.Blog_Grafika_Finalna_URL) || '<i>(brak)</i>'}\n\n<b>Treść:</b> ${esc(pub.Blog_Grafika_Tresc_URL) || '<i>(brak)</i>'}`;
    buttons = standardButtons('featured');
    break;

  case 'blog_preview_pending':
    content = `👀 <b>Preview blogu</b>\n\n<b>${esc(pub.Blog_Tytul)}</b>\n${esc(pub.Blog_Meta_Description)}\n\n<i>Slug: ${esc(pub.Blog_Slug)}</i>`;
    buttons = standardButtons('preview');
    break;

  case 'blog_complete':
    content = `✅ <b>Blog skonczony!</b>`;
    buttons = [
      [{text: '🌐 Publikuj na WordPress', callback_data: `mb:${pubId}:complete:publish_wp`}],
      [{text: '📅 Zaplanuj', callback_data: `mb:${pubId}:complete:schedule_all`}]
    ];
    break;

  case 'session_publishing':
    content = `⏳ <b>Publikuje na wszystkich platformach...</b>`;
    buttons = [];
    break;
  case 'generowanie':
    content = `📝 <b>Generuję bloga…</b>\n\nDaj mi chwilę (~2 min) — zaraz wrzucę sekcje do edycji.`;
    buttons = [];
    break;

  default:
    content = `Nieznany stage: ${esc(stage)}`;
    buttons = [];
}
const navEligible = (String(stage).startsWith('reel_') || String(stage).startsWith('blog_'))
  && stage !== 'reel_render_pending' && stage !== 'reel_draft' && stage !== 'blog_draft';
if (navEligible) {
  buttons = [...buttons, [{ text: '🔙 Wróć do etapu…', callback_data: `mb:${pubId}:nav:menu` }]];
}
return [{
  json: {
    chat_id: chatId,
    text: statusBar + content,
    reply_markup: { inline_keyboard: buttons },
    album: album
  }
}];

const ste = $('State Transition Engine').first().json;
const scope = ste.regen_scope;
const scopeLabels = {
  'hashtags': 'hashtagow',
  'scenariusz': 'skryptu rolki',
  'scenariusz_slide': 'pojedynczego slajdu',
  'fb_text': 'tekstu Facebook',
  'ig_text': 'tekstu Instagram',
  'tiktok_text': 'tekstu TikTok',
  'preview': 'preview rolki',
  'render': 'video',
  'sections': 'tresci bloga',
  'sections_section': 'pojedynczej sekcji bloga',
  'seo': 'SEO bloga',
  'graphics': 'grafik bloga'
};
const label = scopeLabels[scope] || scope;
return [{ json: {
  chat_id: ste.chat_id,
  text: `♻️  <b>Regeneracja ${label}</b>\n\nPodaj poprawki (co konkretnie zmienic) lub kliknij „⏭️ Pomiń" (regen bez wskazowek).`,
  reply_markup: { inline_keyboard: [[{ text: '⏭️ Pomiń', callback_data: `mb:${ste.publication_id}:${scope}:skip` }]] }
}}];

const sesja = $('Get Sesja (text)').first().json;
const input = $('Parse Incoming').first().json;
const text = (input.text || '').trim();
const userCorrection = text === '/skip' ? '' : text;

const pubId = Array.isArray(sesja['Powiązana publikacja'])
  ? sesja['Powiązana publikacja'][0]
  : sesja['Powiązana publikacja'];

return [{
  json: {
    sesja_id: sesja.id,
    publication_id: pubId,
    chat_id: input.chat_id,
    typ_sesji: sesja['Typ Sesji'],
    current_stage: sesja['Aktualny krok'],
    regen_scope: sesja['Regen_Scope_Pending'],
    user_correction: userCorrection,
    regen_slide_num: sesja['Numer_slajdu_edycja'] || 0,
    regen_section_num: sesja['Numer_sekcji_edycja'] || 0
  }
}];

const items = $('Build Music Message').all().map(i => i.json);
const chatId = items[0]?.chat_id;
const media = items
  .filter(it => it.audio_url)
  .map(it => ({ type: 'audio', media: it.audio_url, caption: `${it.index}. ${it.name}`, title: it.name }));
return [{ json: { chat_id: chatId, media } }];

// R4-1: rozbij album na pojedyncze foto + przenies chat_id/caption
const j = $json;
const album = Array.isArray(j.album) ? j.album : [];
return album
  .map(p => ({
    json: {
      chat_id: j.chat_id,
      photo_url: String(p.media || '').trim(),
      caption: String(p.caption || '')
    }
  }))
  .filter(x => x.json.photo_url);

const t = $('State Transition Engine').first().json;
const n = t.delete_section_num;
const pubId = t.publication_id;
return [{
  json: {
    chat_id: t.chat_id,
    text: `🗑️ <b>Usunąć sekcję ${n}?</b>\n\nCała sekcja (nagłówek + treść) zniknie z bloga, a wpis zniknie ze spisu treści. Tej operacji nie cofniesz automatycznie — sekcję odtworzysz tylko regeneracją.\n\nNa pewno?`,
    reply_markup: { inline_keyboard: [[
      { text: '✅ Tak, usuń', callback_data: `mb:${pubId}:sections:delete_confirm_${n}` },
      { text: '❌ Anuluj',    callback_data: `mb:${pubId}:sections:delete_cancel` }
    ]] }
  }
}];

const t = $('State Transition Engine').first().json;
const pubRaw = $('Pobierz-Publikacje-Usun').first().json;
const pub = pubRaw.fields ? pubRaw.fields : pubRaw;
const html = pub['Treść Bloga (HTML)'] || pubRaw['Treść Bloga (HTML)'] || '';
const sectionNum = t.delete_section_num;
const PH = '<!-- GRAFIKA_TRESC -->';

// 1) Podział na sekcje — IDENTYCZNY z Modify Section HTML / Build Stage Message
const sections = [];
const firstH2 = html.search(/<h2/i);
if (firstH2 > 0) {
  sections.push({ start: 0, end: firstH2, content: html.substring(0, firstH2), isLead: true });
}
const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
let m;
while ((m = h2Regex.exec(html)) !== null) {
  sections.push({ start: m.index, end: m.index + m[0].length, content: m[0], isLead: false });
}

// 2) GUARDY (obrona w głąb — UI i tak nie pokaże 🗑️ dla tych przypadkow).
//    W razie naruszenia: zapisujemy HTML bez zmian (no-op) i odswiezamy widok.
const h2count = sections.filter(s => !s.isLead).length;
const noop = () => [{ json: {
  publication_id: t.publication_id, sesja_id: t.sesja_id, chat_id: t.chat_id,
  new_html: html, next_stage: 'blog_sections_pending'
}}];
if (sectionNum < 1 || sectionNum > sections.length) return noop();       // poza zakresem
if (sections[sectionNum - 1].isLead) return noop();                      // Lead (H1+wstep+TOC) — nie usuwamy
if (h2count <= 1) return noop();                                         // ostatnia sekcja H2 — nie usuwamy

const sec = sections[sectionNum - 1];

// 3) Wytnij sekcję. Jesli zawierala placeholder grafiki — wstaw go w to miejsce (granica = koniec poprzedniej / poczatek nastepnej sekcji).
const hadPlaceholder = sec.content.indexOf(PH) !== -1;
const repl = hadPlaceholder ? ('\n' + PH + '\n') : '';
let newHtml = html.substring(0, sec.start) + repl + html.substring(sec.end);

// 4) Usun wpis ze spisu tresci (TOC) po id naglowka sekcji.
const idMatch = sec.content.match(/<h2[^>]*\bid\s*=\s*["']([^"']+)["']/i);
if (idMatch) {
  const id = idMatch[1].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');  // escape do regexa
  const liRx = new RegExp('\\s*<li>\\s*<a[^>]*href\\s*=\\s*["\\\']#' + id + '["\\\'][\\s\\S]*?<\\/li>', 'i');
  newHtml = newHtml.replace(liRx, '');
}

// 5) drobne sprzatanie potrojnych pustych linii
newHtml = newHtml.replace(/\n{3,}/g, '\n\n').trim();

return [{ json: {
  publication_id: t.publication_id,
  sesja_id: t.sesja_id,
  chat_id: t.chat_id,
  new_html: newHtml,
  next_stage: 'blog_sections_pending'
}}];

const pubRaw = $input.first().json;
const pub = pubRaw.fields ? { ...pubRaw.fields, id: pubRaw.id } : pubRaw;
const chatId = $('State Transition Engine').first().json.chat_id;
const pubId = $('State Transition Engine').first().json.publication_id;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => esc(String(s || '').substring(0, n));

const html = pub['Treść Bloga (HTML)'] || '';
const sections = [];

const firstH2 = html.search(/<h2/i);
if (firstH2 > 0) {
  const leadHtml = html.substring(0, firstH2).trim();
  if (leadHtml) {
    sections.push({ id: 1, title: '🎯 Lead (intro + tytul)', length: leadHtml.length });
  }
}

const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
let match;
while ((match = h2Regex.exec(html)) !== null) {
  const title = match[1].replace(/<[^>]+>/g, '').trim();
  sections.push({ id: sections.length + 1, title: title || 'Sekcja', length: match[0].length });
}

let content, buttons;

if (sections.length === 0) {
  content = `📝 <b> Blog gotowy! Sekcje do edycji:</b>\n\n📝 <b>Blog (HTML pusty albo blad
parsowania)</b>\n\n${cut(html, 800)}`;
  buttons = [
    [{text: '✅ Zatwierdz', callback_data: `mb:${pubId}:sections:approve`}, {text: '✏️  Edytuj', callback_data:
 `mb:${pubId}:sections:edit`}],
    [{text: '♻️  Regeneruj', callback_data: `mb:${pubId}:sections:regen`}, {text: '⬅️  Wroc', callback_data:
`mb:${pubId}:sections:back`}]
  ];
} else {
  const menuLines = sections.map(s => `${s.id}. ${esc(s.title.substring(0, 60))} - ${s.length}
znakow`).join('\n');
  content = `📝 <b>Blog gotowy! Sekcje do edycji:</b>\n\n<b>Blog:</b> ⏳ ⬜ ⬜ ⬜ ⬜ ⬜\n\n📝 <b>Tresc bloga
- sekcje do edycji</b>\n\n${menuLines}\n\n<i>Klik numer zeby zobaczyc i edytowac</i>`;

  const sectionButtons = sections.map(s => ({
    text: `✏️  ${s.id}`,
    callback_data: `mb:${pubId}:sections:section_${s.id}`
  }));

  buttons = [];
  for (let r = 0; r < sectionButtons.length; r += 3) {
    buttons.push(sectionButtons.slice(r, r + 3));
  }
  buttons.push([
    { text: '✅ Wszystkie OK', callback_data: `mb:${pubId}:sections:approve` },
    { text: '♻️  Regen', callback_data: `mb:${pubId}:sections:regen` }
  ]);
  buttons.push([
    { text: '⬅️  Wróć', callback_data: `mb:${pubId}:sections:back` }
  ]);
}

return [{
  json: {
    chat_id: chatId,
    text: content,
    reply_markup: { inline_keyboard: buttons }
  }
}];

// C5-A: przesun offset puli muzyki (Aktualny krok zostaje 'wybor_muzyki')
const s = $('Get Sesja for Music CB').first().json;
const f = s.fields || s;
const cbStage = String($('Parse Incoming').first().json.cb_stage || '');
const cur = parseInt(f['Muzyka_Batch_Offset'] || 0, 10) || 0;
const dir = cbStage === '__next__' ? 4 : -4;
return [{ json: {
  sesja_id: s.id,
  chat_id: f['ID chatu Telegram'],
  new_offset: cur + dir     // Build Music Message normalizuje modulo (zawijanie), wiec wartosc ujemna/overflow jest OK
}}];

