parameters.jsCode:
const ste = $('State Transition Engine').first().json;
return [{ json: {
  publication_id: ste.publication_id,
  sesja_id: ste.sesja_id,
  chat_id: ste.chat_id,
  regen_scope: 'graphics',
  user_correction: '',
  regen_slide_num: 0,
  regen_section_num: 0
}}];

const pub = $json.fields || $json;
const cur = [1,2,3].map(n => String(pub[`Blog_Grafika_URL_${n}`] || '').trim());
let hist = [];
try { hist = JSON.parse(pub['Blog_Grafika_Historia'] || '[]'); } catch (e) {}
const last = hist[hist.length - 1];
const already = last && last.join('|') === cur.join('|');
if (cur.every(Boolean) && !already) hist.push(cur);
return [{ json: {
  publication_id: $('State Transition Engine').first().json.publication_id,
  Blog_Grafika_Historia: JSON.stringify(hist)
}}];

const pub = $json.fields || $json;
const cur = [1,2,3].map(n => String(pub[`Blog_Grafika_URL_${n}`] || '').trim());
let hist = [];
try { hist = JSON.parse(pub['Blog_Grafika_Historia'] || '[]'); } catch (e) {}
if (cur.every(Boolean)) hist.push(cur);
return [{ json: {
  publication_id: $('State Transition Engine').first().json.publication_id,
  Blog_Grafika_Historia: JSON.stringify(hist),
  Blog_Grafika_Historia_Idx: Math.max(0, hist.length - 1),
  Blog_Grafika_Wybrana_Hero: '',
  Blog_Grafika_Finalna_URL: '',
  Blog_Grafika_Tresc_URL: ''
}}];

const pub = $json.fields || $json;
let hist = [];
try { hist = JSON.parse(pub['Blog_Grafika_Historia'] || '[]'); } catch (e) {}
const dir = $('State Transition Engine').first().json.history_dir || 0;
let idx = parseInt(pub['Blog_Grafika_Historia_Idx'] || 0, 10) || 0;
idx = Math.min(hist.length - 1, Math.max(0, idx + dir));
const batch = hist[idx] || ['', '', ''];
return [{ json: {
  publication_id: $('State Transition Engine').first().json.publication_id,
  Blog_Grafika_URL_1: batch[0] || '',
  Blog_Grafika_URL_2: batch[1] || '',
  Blog_Grafika_URL_3: batch[2] || '',
  Blog_Grafika_Historia_Idx: idx,
  Blog_Grafika_Wybrana_Hero: '',
  Blog_Grafika_Finalna_URL: '',
  Blog_Grafika_Tresc_URL: ''
}}];
